/** Languages Eventual ships besides English (the source language, always built in). */
export const LOCALES = ["fr", "de", "nl", "es", "it", "pt", "pt-BR", "pl", "cs", "sv", "da", "nb", "fi", "ja", "zh-CN", "ko", "tr", "uk", "ar", "he"];

const ALIASES = { no: "nb", nn: "nb", iw: "he", "zh-Hans": "zh-CN", "zh-SG": "zh-CN", "zh-MY": "zh-CN" };

/**
 * Best shipped language for a BCP 47 tag, or "en". Accepts `_` separators and any case.
 * pt-BR is distinct from pt (European). Traditional Chinese falls back to English rather
 * than showing the wrong script.
 */
export function resolveLocale(input, available = LOCALES) {
  let tag;
  try { tag = Intl.getCanonicalLocales(String(input || "").trim().replace(/_/g, "-"))[0]; } catch {}
  if (!tag) return "en";
  const [lang, ...rest] = tag.split("-");
  const script = rest.find((part) => part.length === 4);
  const region = rest.find((part) => part.length === 2 || /^\d{3}$/.test(part));
  const candidates = [];
  if (lang === "zh") {
    if (script === "Hant" || (!script && ["TW", "HK", "MO"].includes(region))) return "en";
    candidates.push("zh-CN");
  }
  if (region) candidates.push(`${lang}-${region}`, ALIASES[`${lang}-${region}`]);
  if (script) candidates.push(ALIASES[`${lang}-${script}`]);
  candidates.push(lang, ALIASES[lang]);
  for (const candidate of candidates) if (candidate === "en" || available.includes(candidate)) return candidate;
  return "en";
}

/** Text direction for a shipped language. */
export function localeDirection(locale) {
  return /^(ar|he|fa|ur)\b/.test(String(locale)) ? "rtl" : "ltr";
}
